#include <stdio.h>

void knapsack(int n, int w[], int p[], int cap);

void main()
{
    int n, i, cap;
    int w[20], p[20];

    printf("Enter number of items: ");
    scanf("%d", &n);

    printf("Enter weight of items:\n");
    for(i = 0; i < n; i++)
    {
        scanf("%d", &w[i]);
    }

    printf("Enter profit of items:\n");
    for(i = 0; i < n; i++)
    {
        scanf("%d", &p[i]);
    }

    printf("Enter capacity of knapsack: ");
    scanf("%d", &cap);

    knapsack(n, w, p, cap);
}


/* Knapsack Function */

void knapsack(int n, int w[], int p[], int cap)
{
    int i, j, temp;
    float ratio[20], x[20];
    float profit = 0;

    /* Calculate Profit/Weight ratio */
    for(i = 0; i < n; i++)
    {
        ratio[i] = (float)p[i] / w[i];
        x[i] = 0;
    }

    /* Sort according to Profit/Weight ratio */
    for(i = 0; i < n - 1; i++)
    {
        for(j = i + 1; j < n; j++)
        {
            if(ratio[i] < ratio[j])
            {
                temp = w[i];
                w[i] = w[j];
                w[j] = temp;

                temp = p[i];
                p[i] = p[j];
                p[j] = temp;

                float t = ratio[i];
                ratio[i] = ratio[j];
                ratio[j] = t;
            }
        }
    }

    /* Select items */
    for(i = 0; i < n; i++)
    {
        if(w[i] <= cap)
        {
            x[i] = 1;
            profit = profit + p[i];
            cap = cap - w[i];
        }
        else
        {
            x[i] = (float)cap / w[i];
            profit = profit + x[i] * p[i];
            cap = 0;
            break;
        }
    }

    printf("\nMaximum Profit = %.0f", profit);
}

